请对以下 case 进行三维加权评分。

=== case_id ===
Case-17-queue-005

=== 用户原始指令 (query.txt) ===
整个排队卡 点一下能进应用 顺便读个天气 显示已经连上了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个排队卡 点一下能进应用 顺便读个天气 显示已经连上了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "bluetooth_entry"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "queue": {
        "title": {
          "type": "string",
          "description": "排队叫号卡片标题",
          "sampleValue": "排队叫号"
        },
        "currentNumber": {
          "type": "string",
          "description": "当前正在呼叫的排队号码",
          "sampleValue": "A128"
        },
        "caption": {
          "type": "string",
          "description": "当前号码的简短状态说明",
          "sampleValue": "当前叫号"
        },
        "deskText": {
          "type": "string",
          "description": "办理窗口或队列位置提示",
          "sampleValue": "请到 3 号窗口"
        },
        "connectionStatus": {
          "type": "string",
          "description": "服务连接确认状态",
          "sampleValue": "已连接"
        },
        "actionHint": {
          "type": "string",
          "description": "整卡点击进入目标应用的短提示",
          "sampleValue": "点按进入"
        }
      },
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

